// Generated by build.py from ui/; edit those files instead.
import { host, PALETTE_AREA, ROUTES_AREA, SIDEBAR_NAV_AREA, STATUSBAR_AREAS } from '@hermes/plugin-sdk'
import * as React from 'react'

const ID = 'hermes-mail-gate'
const ROUTE = '/mail-gate'

function createMailGate(React, api) {
  const h = React.createElement
  const { useCallback, useEffect, useMemo, useState } = React

  const C = {
    text: 'var(--ui-text-primary, var(--color-foreground, currentColor))',
    muted: 'var(--ui-text-secondary, var(--color-muted-foreground, #8a8f98))',
    faint: 'var(--ui-text-tertiary, var(--color-muted-foreground, #a0a4ab))',
    border: 'var(--ui-stroke-secondary, var(--color-border, rgba(128, 128, 128, 0.28)))',
    accent: 'var(--ui-accent, var(--color-primary, #4f7cff))',
    green: 'var(--ui-green, #2e9d5b)',
    blue: 'var(--ui-blue, #3b82f6)',
    orange: 'var(--ui-orange, #e08a1e)',
    red: 'var(--ui-red, #d64545)',
    purple: 'var(--ui-purple, #8b5cf6)'
  }
  const OUTCOMES = {
    delivered: { label: 'Delivered', color: C.green },
    released: { label: 'Released', color: C.blue },
    held: { label: 'Held', color: C.orange },
    'dropped-blocked': { label: 'Blocked', color: C.red },
    'dropped-unauthenticated': { label: 'Unauthenticated', color: C.purple }
  }
  const ACTION_COLORS = { allow: C.green, block: C.red, trust: C.blue }
  const GLOBAL = '*'

  const s = {
    page: { padding: '20px 24px', color: C.text, fontSize: 13, lineHeight: 1.45, maxWidth: 1180 },
    header: { display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 12, marginBottom: 4 },
    title: { fontSize: 18, fontWeight: 600, margin: 0 },
    subtitle: { color: C.muted, margin: '0 0 16px' },
    tabs: { display: 'flex', gap: 4, borderBottom: `1px solid ${C.border}`, marginBottom: 16 },
    tab: active => ({
      padding: '7px 12px', border: 'none', background: 'none', cursor: 'pointer', fontSize: 13,
      color: active ? C.text : C.muted, fontWeight: active ? 600 : 400,
      borderBottom: `2px solid ${active ? C.accent : 'transparent'}`, marginBottom: -1
    }),
    row: { display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap', marginBottom: 12 },
    table: { width: '100%', borderCollapse: 'collapse' },
    th: { textAlign: 'left', fontWeight: 500, color: C.muted, padding: '6px 8px', borderBottom: `1px solid ${C.border}`,
      whiteSpace: 'nowrap', fontSize: 12 },
    td: { padding: '7px 8px', borderBottom: `1px solid ${C.border}`, verticalAlign: 'top' },
    button: (tone, solid) => ({
      padding: '4px 9px', borderRadius: 6, cursor: 'pointer', fontSize: 12, whiteSpace: 'nowrap',
      border: `1px solid ${tone || C.border}`, background: solid ? tone : 'transparent',
      color: solid ? '#fff' : tone || C.text
    }),
    input: { padding: '5px 8px', borderRadius: 6, border: `1px solid ${C.border}`, background: 'transparent',
      color: C.text, fontSize: 12, minWidth: 0 },
    badge: color => ({
      display: 'inline-block', padding: '1px 7px', borderRadius: 999, fontSize: 11, fontWeight: 500,
      color, border: `1px solid ${color}`, whiteSpace: 'nowrap'
    }),
    note: { color: C.muted, fontSize: 12 },
    error: { color: C.red, fontSize: 12, margin: '8px 0' },
    warn: { color: C.orange, fontSize: 12 },
    mono: { fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace', fontSize: 12 },
    empty: { color: C.muted, padding: '28px 0', textAlign: 'center' },
    scroll: { overflowX: 'auto' }
  }

  function ago(iso) {
    if (!iso) return ''
    const seconds = Math.max(0, (Date.now() - new Date(iso).getTime()) / 1000)
    if (seconds < 90) return 'just now'
    if (seconds < 5400) return `${Math.round(seconds / 60)} min ago`
    if (seconds < 129600) return `${Math.round(seconds / 3600)} h ago`
    return `${Math.round(seconds / 86400)} d ago`
  }

  function when(iso) {
    return iso ? new Date(iso).toLocaleString() : ''
  }

  function useLoad(loader, deps) {
    const [state, setState] = useState({ data: null, error: null, loading: true })
    const reload = useCallback(() => {
      setState(prev => ({ ...prev, loading: true }))
      return loader()
        .then(data => setState({ data, error: null, loading: false }))
        .catch(error => setState({ data: null, error: String(error && error.message || error), loading: false }))
    }, deps)
    useEffect(() => { reload() }, [reload])
    return [state, reload]
  }

  function Badge({ color, children }) {
    return h('span', { style: s.badge(color) }, children)
  }

  function Select({ value, onChange, options, label }) {
    return h('select', { value, onChange: e => onChange(e.target.value), style: s.input, 'aria-label': label },
      options.map(([v, text]) => h('option', { key: v, value: v }, text)))
  }

  function botOptions(bots, withAll, withGlobal) {
    const options = []
    if (withAll) options.push(['', 'All bots'])
    if (withGlobal) options.push([GLOBAL, 'Every bot (*)'])
    return options.concat(bots.map(b => [b.bot, b.address || b.bot]))
  }

  function Pending({ bots, version, onChanged }) {
    const [state, reload] = useLoad(() => api.get('/pending'), [version])
    const [busy, setBusy] = useState('')
    const [armed, setArmed] = useState('')
    const [error, setError] = useState('')

    const decide = (row, action, scope) => {
      const key = `${row.bot}|${row.sender}|${action}|${scope}`
      if (action === 'trust' && scope === 'domain' && armed !== key) {
        setArmed(key)
        return
      }
      setBusy(key)
      setError('')
      api.post('/decide', { bot: row.bot, sender: row.sender, scope, action })
        .then(() => { setArmed(''); return reload() })
        .then(onChanged)
        .catch(err => setError(String(err && err.message || err)))
        .finally(() => setBusy(''))
    }

    if (state.error) return h('div', { style: s.error }, state.error)
    const rows = (state.data && state.data.pending) || []
    if (!rows.length) return h('div', { style: s.empty }, state.loading ? 'Loading…' : 'No senders are waiting for a decision.')
    const address = bot => (bots.find(b => b.bot === bot) || {}).address || bot

    return h('div', null,
      h('p', { style: s.note }, 'Authenticated senders no rule covers yet. Their mail stays in the mailbox until you decide; ',
        'allowing re-runs it through the gate, blocking drops it.'),
      error && h('div', { style: s.error }, error),
      h('div', { style: s.scroll }, h('table', { style: s.table },
        h('thead', null, h('tr', null, ['Mailbox', 'Sender', 'Messages', 'Waiting', 'Latest subject', 'Decision']
          .map(t => h('th', { key: t, style: s.th }, t)))),
        h('tbody', null, rows.map(row => {
          const button = (label, action, scope, tone) => {
            const key = `${row.bot}|${row.sender}|${action}|${scope}`
            const confirming = armed === key
            return h('button', {
              key: label, type: 'button', disabled: !!busy, onClick: () => decide(row, action, scope),
              style: s.button(tone, confirming), title: `${label} for ${address(row.bot)}`
            }, confirming ? `Confirm: trust all of ${row.sender_domain}` : busy === key ? '…' : label)
          }
          return h('tr', { key: `${row.bot}|${row.sender}` },
            h('td', { style: s.td }, address(row.bot)),
            h('td', { style: s.td }, h('div', null, row.sender), h('div', { style: s.note }, row.auth)),
            h('td', { style: s.td }, row.messages),
            h('td', { style: s.td, title: when(row.first_at) }, ago(row.first_at)),
            h('td', { style: { ...s.td, maxWidth: 280 } }, row.last_subject),
            h('td', { style: s.td }, h('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' } },
              button('Allow address', 'allow', 'address', C.green),
              button('Allow domain', 'allow', 'domain', C.green),
              button('Block address', 'block', 'address', C.red),
              button('Block domain', 'block', 'domain', C.red),
              button('Trust address', 'trust', 'address', C.blue),
              button('Trust domain', 'trust', 'domain', C.blue))))
        })))))
  }

  function Rules({ bots }) {
    const [bot, setBot] = useState('')
    const [state, reload] = useLoad(() => api.get(`/rules${bot ? `?bot=${encodeURIComponent(bot)}` : ''}`), [bot])
    const [form, setForm] = useState({ bot: GLOBAL, action: 'allow', scope: 'domain', value: '' })
    const [error, setError] = useState('')
    const [result, setResult] = useState('')

    const add = () => {
      setError('')
      setResult('')
      api.post('/rules', form)
        .then(r => {
          setResult(r.held_processed ? `Saved. ${r.held_processed} held message(s) re-run through the gate.` : 'Saved.')
          setForm({ ...form, value: '' })
          return reload()
        })
        .catch(err => setError(String(err && err.message || err)))
    }
    const remove = rule => api.post('/rules/delete', rule).then(reload).catch(err => setError(String(err && err.message || err)))
    const address = value => value === GLOBAL ? 'Every bot (*)' : (bots.find(b => b.bot === value) || {}).address || value
    const rows = (state.data && state.data.rules) || []
    const domainTrust = form.action === 'trust' && form.scope === 'domain'

    return h('div', null,
      h('div', { style: s.row },
        h(Select, { label: 'Rule bot', value: form.bot, onChange: v => setForm({ ...form, bot: v }), options: botOptions(bots, false, true) }),
        h(Select, { label: 'Action', value: form.action, onChange: v => setForm({ ...form, action: v }),
          options: [['allow', 'Allow'], ['block', 'Block'], ['trust', 'Trust (full tools)']] }),
        h(Select, { label: 'Scope', value: form.scope, onChange: v => setForm({ ...form, scope: v }),
          options: [['domain', 'Domain'], ['address', 'Address']] }),
        h('input', { style: { ...s.input, width: 260 }, value: form.value, placeholder: form.scope === 'domain' ? 'vendor.com' : 'person@vendor.com',
          onChange: e => setForm({ ...form, value: e.target.value }), onKeyDown: e => e.key === 'Enter' && add() }),
        h('button', { type: 'button', style: s.button(C.accent, true), onClick: add, disabled: !form.value.trim() }, 'Add rule')),
      domainTrust && h('p', { style: s.warn }, 'Trusting a domain gives full tools to every authenticated address on it.'),
      error && h('div', { style: s.error }, error),
      result && h('p', { style: s.note }, result),
      h('div', { style: s.row }, h('span', { style: s.note }, 'Show'),
        h(Select, { label: 'Filter bot', value: bot, onChange: setBot, options: botOptions(bots, true, false) }),
        h('span', { style: s.note }, 'The most specific rule wins: this bot\'s address, this bot\'s domain, then the same for every bot.')),
      rows.length === 0
        ? h('div', { style: s.empty }, state.loading ? 'Loading…' : 'No rules yet.')
        : h('div', { style: s.scroll }, h('table', { style: s.table },
          h('thead', null, h('tr', null, ['Applies to', 'Action', 'Scope', 'Value', 'Since', '']
            .map(t => h('th', { key: t, style: s.th }, t)))),
          h('tbody', null, rows.map(rule => h('tr', { key: `${rule.bot}|${rule.scope}|${rule.value}` },
            h('td', { style: s.td }, address(rule.bot)),
            h('td', { style: s.td }, h(Badge, { color: ACTION_COLORS[rule.action] }, rule.action)),
            h('td', { style: s.td }, rule.scope),
            h('td', { style: { ...s.td, ...s.mono } }, rule.value),
            h('td', { style: s.td, title: when(rule.created_at) }, ago(rule.created_at)),
            h('td', { style: { ...s.td, textAlign: 'right' } },
              h('button', { type: 'button', style: s.button(), onClick: () => remove(rule) }, 'Remove'))))))))
  }

  function Activity({ bots, version }) {
    const [bot, setBot] = useState('')
    const [outcome, setOutcome] = useState('')
    const [events, setEvents] = useState([])
    const [more, setMore] = useState(false)
    const [error, setError] = useState('')
    const query = before => {
      const params = new URLSearchParams({ limit: '100' })
      if (bot) params.set('bot', bot)
      if (outcome) params.set('outcome', outcome)
      if (before) params.set('before', String(before))
      return api.get(`/events?${params}`)
    }
    useEffect(() => {
      setError('')
      query().then(r => { setEvents(r.events); setMore(r.events.length === 100) }).catch(err => setError(String(err && err.message || err)))
    }, [bot, outcome, version])
    const loadMore = () => query(events[events.length - 1].id)
      .then(r => { setEvents(events.concat(r.events)); setMore(r.events.length === 100) })
      .catch(err => setError(String(err && err.message || err)))

    return h('div', null,
      h('div', { style: s.row },
        h(Select, { label: 'Bot', value: bot, onChange: setBot, options: botOptions(bots, true, false) }),
        h(Select, { label: 'Outcome', value: outcome, onChange: setOutcome,
          options: [['', 'All outcomes']].concat(Object.entries(OUTCOMES).map(([k, v]) => [k, v.label])) }),
        h('span', { style: s.note }, 'Metadata only: bodies are never logged. Kept for 90 days.')),
      error && h('div', { style: s.error }, error),
      events.length === 0
        ? h('div', { style: s.empty }, 'No activity yet.')
        : h('div', { style: s.scroll }, h('table', { style: s.table },
          h('thead', null, h('tr', null, ['When', 'Mailbox', 'Outcome', 'Sender', 'Subject', 'Files', 'Authentication']
            .map(t => h('th', { key: t, style: s.th }, t)))),
          h('tbody', null, events.map(e => h('tr', { key: e.id },
            h('td', { style: { ...s.td, whiteSpace: 'nowrap' }, title: when(e.at) }, ago(e.at)),
            h('td', { style: s.td }, e.bot),
            h('td', { style: s.td }, h(Badge, { color: (OUTCOMES[e.outcome] || {}).color || C.muted },
              (OUTCOMES[e.outcome] || {}).label || e.outcome), e.route === 'mail-trusted' ? h('span', { style: { ...s.note, marginLeft: 6 } }, 'trusted') : null),
            h('td', { style: s.td }, e.sender),
            h('td', { style: { ...s.td, maxWidth: 320 } }, e.subject),
            h('td', { style: s.td }, e.attachments || ''),
            h('td', { style: { ...s.td, ...s.note } }, e.auth)))))),
      more && h('div', { style: { marginTop: 12 } }, h('button', { type: 'button', style: s.button(), onClick: loadMore }, 'Load more')))
  }

  function Chart({ buckets, series }) {
    const width = 760
    const height = 220
    const pad = { top: 10, right: 8, bottom: 28, left: 34 }
    const max = Math.max(1, ...buckets.map(b => series.reduce((sum, key) => sum + (b.values[key] || 0), 0)))
    const innerW = width - pad.left - pad.right
    const innerH = height - pad.top - pad.bottom
    const slot = innerW / Math.max(1, buckets.length)
    const barW = Math.max(3, Math.min(28, slot * 0.7))
    const ticks = [0, Math.ceil(max / 2), max]
    const labelEvery = Math.ceil(buckets.length / 10)
    return h('svg', { viewBox: `0 0 ${width} ${height}`, width: '100%', role: 'img', 'aria-label': 'Gate outcomes over time',
      style: { maxWidth: width, display: 'block' } },
      ticks.map(t => {
        const y = pad.top + innerH - (t / max) * innerH
        return h('g', { key: `t${t}` },
          h('line', { x1: pad.left, x2: width - pad.right, y1: y, y2: y, stroke: C.border, strokeWidth: 1 }),
          h('text', { x: pad.left - 6, y: y + 4, textAnchor: 'end', fontSize: 10, fill: C.muted }, t))
      }),
      buckets.map((b, i) => {
        let y = pad.top + innerH
        const x = pad.left + i * slot + (slot - barW) / 2
        return h('g', { key: b.bucket },
          series.map(key => {
            const value = b.values[key] || 0
            if (!value) return null
            const segment = (value / max) * innerH
            y -= segment
            return h('rect', { key, x, y, width: barW, height: Math.max(segment, 1), fill: OUTCOMES[key].color, rx: 1.5 },
              h('title', null, `${b.bucket} · ${OUTCOMES[key].label}: ${value}`))
          }),
          i % labelEvery === 0 && h('text', { x: x + barW / 2, y: height - 10, textAnchor: 'middle', fontSize: 10, fill: C.muted },
            b.label))
      }))
  }

  function bucketsFor(period, count) {
    const out = []
    const now = new Date()
    for (let i = count - 1; i >= 0; i--) {
      if (period === 'day') {
        const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - i))
        const key = d.toISOString().slice(0, 10)
        out.push({ bucket: key, label: key.slice(5) })
      } else if (period === 'month') {
        const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - i, 1))
        const key = d.toISOString().slice(0, 7)
        out.push({ bucket: key, label: key })
      } else {
        const d = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - i * 7))
        const yearDay = Math.floor((d - new Date(Date.UTC(d.getUTCFullYear(), 0, 1))) / 86400000)
        const mondayWeek = Math.floor((yearDay + 7 - ((d.getUTCDay() + 6) % 7)) / 7)
        const key = `${d.getUTCFullYear()}-W${String(mondayWeek).padStart(2, '0')}`
        if (!out.some(b => b.bucket === key)) out.push({ bucket: key, label: key.slice(5) })
      }
    }
    return out
  }

  function Stats({ bots, version }) {
    const [period, setPeriod] = useState('day')
    const [bot, setBot] = useState('')
    const count = { day: 30, week: 12, month: 12 }[period]
    const [state] = useLoad(() => api.get(`/stats?period=${period}&buckets=${count}${bot ? `&bot=${encodeURIComponent(bot)}` : ''}`), [period, bot, version])
    const series = Object.keys(OUTCOMES)
    const buckets = useMemo(() => {
      const frame = bucketsFor(period, count).map(b => ({ ...b, values: {} }))
      const index = Object.fromEntries(frame.map(b => [b.bucket, b]))
      for (const row of (state.data && state.data.rows) || []) {
        const target = index[row.bucket]
        if (target) target.values[row.outcome] = (target.values[row.outcome] || 0) + row.total
      }
      return frame
    }, [state.data, period, count])
    const totals = series.map(key => [key, buckets.reduce((sum, b) => sum + (b.values[key] || 0), 0)])
    const perBot = useMemo(() => {
      const table = {}
      for (const row of (state.data && state.data.rows) || []) {
        table[row.bot] = table[row.bot] || {}
        table[row.bot][row.outcome] = (table[row.bot][row.outcome] || 0) + row.total
      }
      return Object.entries(table).sort(([a], [b]) => a.localeCompare(b))
    }, [state.data])

    return h('div', null,
      h('div', { style: s.row },
        ['day', 'week', 'month'].map(p => h('button', { key: p, type: 'button', onClick: () => setPeriod(p), style: s.button(period === p ? C.accent : null, period === p) },
          { day: 'Last 30 days', week: 'Last 12 weeks', month: 'Last 12 months' }[p])),
        h(Select, { label: 'Bot', value: bot, onChange: setBot, options: botOptions(bots, true, false) })),
      state.error ? h('div', { style: s.error }, state.error) : h(Chart, { buckets, series }),
      h('div', { style: { ...s.row, marginTop: 10 } }, totals.map(([key, total]) => h('span', { key, style: { display: 'inline-flex', gap: 6, alignItems: 'center', marginRight: 14 } },
        h('span', { style: { width: 10, height: 10, borderRadius: 2, background: OUTCOMES[key].color, display: 'inline-block' } }),
        h('span', null, `${OUTCOMES[key].label}: `, h('strong', null, total))))),
      perBot.length > 0 && h('div', { style: { ...s.scroll, marginTop: 8 } }, h('table', { style: s.table },
        h('thead', null, h('tr', null, [h('th', { key: 'bot', style: s.th }, 'Mailbox')].concat(series.map(k => h('th', { key: k, style: { ...s.th, textAlign: 'right' } }, OUTCOMES[k].label))))),
        h('tbody', null, perBot.map(([name, values]) => h('tr', { key: name },
          h('td', { style: s.td }, name),
          series.map(k => h('td', { key: k, style: { ...s.td, textAlign: 'right' } }, values[k] || 0))))))))
  }

  function App() {
    const [tab, setTab] = useState('pending')
    const [bots, setBots] = useState([])
    const [summary, setSummary] = useState(null)
    const refreshSummary = useCallback(() => api.get('/summary').then(setSummary).catch(() => {}), [])
    useEffect(() => {
      api.get('/bots').then(r => setBots(r.bots)).catch(() => {})
      refreshSummary()
      const timer = setInterval(refreshSummary, 15000)
      return () => clearInterval(timer)
    }, [refreshSummary])
    const pendingCount = summary ? summary.pending_senders : 0
    const version = summary ? JSON.stringify([summary.pending_keys, summary.today]) : ''
    const tabs = [['pending', pendingCount ? `Pending (${pendingCount})` : 'Pending'], ['rules', 'Rules'], ['activity', 'Activity'], ['stats', 'Stats']]

    return h('div', { style: s.page },
      h('div', { style: s.header }, h('h2', { style: s.title }, 'Mail Gate'),
        summary && h('span', { style: s.note }, `Today: ${Object.entries(summary.today).map(([k, v]) => `${(OUTCOMES[k] || {}).label || k} ${v}`).join(' · ') || 'no mail yet'}`)),
      h('p', { style: s.subtitle }, 'Every email to a bot passes this gate before any AI reads it: unauthenticated senders are dropped, ',
        'rules decide the rest, and unknown senders wait here for you.'),
      h('div', { style: s.tabs, role: 'tablist' }, tabs.map(([key, label]) => h('button', {
        key, type: 'button', role: 'tab', 'aria-selected': tab === key, style: s.tab(tab === key), onClick: () => setTab(key)
      }, label))),
      tab === 'pending' && h(Pending, { bots, version, onChanged: refreshSummary }),
      tab === 'rules' && h(Rules, { bots }),
      tab === 'activity' && h(Activity, { bots, version }),
      tab === 'stats' && h(Stats, { bots, version }))
  }

  return App
}

function StatusCount({ ctx }) {
  const [count, setCount] = React.useState(0)
  React.useEffect(() => {
    let alive = true
    const load = () => ctx.rest('/summary').then(r => alive && setCount(r.pending_senders)).catch(() => {})
    load()
    const timer = setInterval(load, 30000)
    return () => { alive = false; clearInterval(timer) }
  }, [])
  if (!count) return null
  return React.createElement('button', {
    type: 'button', onClick: () => host.navigate(ROUTE), title: 'Senders waiting for your decision in Mail Gate',
    style: { display: 'inline-flex', alignItems: 'center', height: '100%', padding: '0 6px', fontSize: 11, border: 'none',
      background: 'none', cursor: 'pointer', color: 'var(--ui-orange, #e08a1e)', fontVariantNumeric: 'tabular-nums' }
  }, `✉ ${count} pending`)
}

export default {
  id: ID,
  name: 'Mail Gate',
  description: 'Allow, block and trust rules for the bots\' mailboxes, senders waiting for a decision, and gate activity.',
  register(ctx) {
    const api = {
      get: path => ctx.rest(path),
      post: (path, body) => ctx.rest(path, { method: 'POST', body })
    }
    const App = createMailGate(React, api)
    ctx.registerMany([
      { id: 'page', area: ROUTES_AREA, data: { path: ROUTE }, render: () => React.createElement(App) },
      { id: 'nav', area: SIDEBAR_NAV_AREA, data: { path: ROUTE, label: 'Mail Gate', codicon: 'mail' } },
      { id: 'open', area: PALETTE_AREA, data: { id: `${ID}.open`, label: 'Open Mail Gate', run: () => host.navigate(ROUTE) } },
      { id: 'count', area: STATUSBAR_AREAS.right, order: 120, render: () => React.createElement(StatusCount, { ctx }) }
    ])

    let known = null
    const poll = () => ctx.rest('/summary').then(summary => {
      const keys = new Set(summary.pending_keys || [])
      if (known) {
        const fresh = [...keys].filter(key => !known.has(key))
        if (fresh.length) {
          const [bot, sender] = fresh[0].split('|')
          ctx.os.notify({
            title: 'Mail Gate: new sender waiting',
            body: fresh.length === 1 ? `${sender} wrote to ${bot}. Allow or block it.` : `${fresh.length} new senders are waiting for your decision.`,
            activate: ROUTE
          })
        }
      }
      known = keys
    }).catch(() => {})
    poll()
    ctx.setInterval(poll, 60000)
  }
}
